## Design Note

- **State machine** with explicit phases for strings (normal/escape/unicode), numbers (7 sub-phases matching the JSON number grammar), literals (position tracker), and a nesting stack for containers.
- **Buffer**: a `list[str]` accumulating the current top-level value's characters; joined once on completion (O(1) amortized per char, no re-scan).
- **Container stack**: each entry is `[is_object, expectation]` where expectation ∈ {key, colon, value, comma_or_close}. Depth is stack length.
- **Top-level terminator**: numbers/literals go to `_after_top` state at end-of-feed; the next char (whitespace, `{`, `[`, `"`) finalises them. Self-delimiting values (strings, containers) complete immediately.
- **Complexity**: each character is visited exactly once → O(n) total, independent of chunk boundaries. `json.loads` is called once per value on its text.
- **Thread safety**: not required (one connection per decoder).

### solution.py
```python
"""Incremental JSON stream decoder for log ingestion (RFC 8259, stdlib-only)."""
from __future__ import annotations
import json
from typing import Any


class JSONStreamError(ValueError):
    def __init__(self, msg: str = "", offset: int = 0):
        super().__init__(msg)
        self.offset = offset


class IncompleteJSONError(JSONStreamError):
    def __init__(self, msg: str = "Incomplete JSON", offset: int = 0):
        super().__init__(msg, offset)


class BufferLimitError(JSONStreamError):
    def __init__(self, msg: str = "Buffer limit exceeded", offset: int = 0):
        super().__init__(msg, offset)


class JSONStreamDecoder:
    def __init__(self, *, max_buffer: int = 10_000_000) -> None:
        if not isinstance(max_buffer, int) or isinstance(max_buffer, bool) or max_buffer < 1:
            raise ValueError("max_buffer must be an int >= 1")
        self._max_buffer = max_buffer
        self._offset: int = 0
        self._closed = False
        self._errored = False
        self._buf: list[str] = []
        self._val_start: int = 0
        self._stack: list[list] = []
        self._depth: int = 0
        self._in_str: bool = False
        self._str_phase: int = 0
        self._uni_left: int = 0
        self._num_phase: int = 0
        self._lit_target: str = ""
        self._lit_pos: int = 0
        self._after_top: str | None = None

    # ---- public API ----

    def feed(self, chunk: str) -> list[Any]:
        if not isinstance(chunk, str):
            raise TypeError("chunk must be a str")
        if self._closed or self._errored:
            raise JSONStreamError("Decoder is closed", self._offset)
        results: list[Any] = []
        for ch in chunk:
            val = self._step(ch)
            if val is not None:
                results.append(val)
            self._offset += 1
        # If a top-level number is at a syntactically valid end, mark it as
        # waiting for a terminator (spec: not returned until terminator seen).
        if (self._after_top is None
                and not self._in_str
                and not self._lit_target
                and self._depth == 0
                and self._num_phase in (2, 3, 5, 8)):
            self._after_top = "number"
        return results

    def close(self) -> list[Any]:
        if self._errored:
            raise JSONStreamError("Decoder is closed", self._offset)
        if self._closed:
            raise JSONStreamError("Decoder is closed", self._offset)
        self._closed = True
        if self._in_str or self._lit_target or self._depth > 0:
            raise IncompleteJSONError("Incomplete JSON", self._offset)
        if self._num_phase:
            # Number in progress at a non-terminal phase (1,4,6,7)
            raise IncompleteJSONError("Incomplete JSON", self._offset)
        if self._after_top:
            return [self._decode()]
        return []

    def pending(self) -> int:
        if self._closed or self._errored:
            return 0
        return len(self._buf)

    # ---- internal state machine ----

    def _step(self, ch: str) -> Any | None:
        if self._after_top is not None:
            return self._after_top_char(ch)
        if self._in_str:
            return self._string_char(ch)
        if self._lit_target:
            return self._literal_char(ch)
        if self._num_phase:
            return self._number_char(ch)
        if self._depth > 0:
            return self._container_char(ch)
        return self._between_char(ch)

    # Between top-level values: skip whitespace, start new value, or error.
    def _between_char(self, ch: str) -> Any | None:
        if ch in ' \t\n\r':
            return None
        if ch in '{[\"tfn-' or ch.isdigit():
            self._begin_value(ch)
            return None
        self._fail()

    # Top-level number/literal waiting for its terminating character.
    def _after_top_char(self, ch: str) -> Any | None:
        if ch in ' \t\n\r{[\"':
            val = self._decode()
            self._after_top = None
            if ch in '{[\"':
                self._begin_value(ch)
            return val
        if self._after_top == "number" and ch.isdigit():
            self._after_top = None
            self._buf_append(ch)
            self._num_phase = 2
            return None
        if self._after_top == "number" and ch == '.':
            self._after_top = None
            self._buf_append(ch)
            self._num_phase = 4
            return None
        if self._after_top == "number" and ch in 'eE':
            self._after_top = None
            self._buf_append(ch)
            self._num_phase = 6
            return None
        self._fail()

    # ---- container grammar ----

    def _container_char(self, ch: str) -> Any | None:
        if ch in ' \t\n\r':
            return None
        is_obj, expect = self._stack[-1]
        if expect == "key":
            if ch == '"':
                self._buf_append(ch)
                self._in_str = True
                self._str_phase = 0
            elif ch == '}':
                return self._close_container()
            else:
                self._fail()
        elif expect == "colon":
            if ch == ':':
                self._buf_append(ch)
                self._stack[-1][1] = "value"
            else:
                self._fail()
        elif expect == "value":
            if not is_obj and ch == ']':
                return self._close_container()
            if ch in '{[\"tfn-' or ch.isdigit():
                self._begin_nested(ch)
            else:
                self._fail()
        elif expect == "comma_or_close":
            if ch == ',':
                self._buf_append(ch)
                self._stack[-1][1] = "key" if is_obj else "value"
            elif ch == ('}' if is_obj else ']'):
                return self._close_container()
            else:
                self._fail()
        return None

    def _close_container(self) -> Any | None:
        self._buf_append('}' if self._stack[-1][0] else ']')
        self._stack.pop()
        self._depth -= 1
        if self._depth == 0:
            return self._decode()
        self._stack[-1][1] = "comma_or_close"
        return None

    # ---- string parsing ----

    def _string_char(self, ch: str) -> Any | None:
        if self._str_phase == 0:
            if ch == '"':
                self._buf_append(ch)
                self._in_str = False
                return self._end_string()
            if ch == '\\':
                self._buf_append(ch)
                self._str_phase = 1
            elif ord(ch) < 0x20:
                self._fail()
            else:
                self._buf_append(ch)
            return None
        if self._str_phase == 1:
            if ch in '"\\/bfnrt':
                self._buf_append(ch)
                self._str_phase = 0
            elif ch == 'u':
                self._buf_append(ch)
                self._str_phase = 2
                self._uni_left = 4
            else:
                self._fail()
            return None
        # phase 2: collecting \uXXXX hex digits
        if ch in '0123456789abcdefABCDEF':
            self._buf_append(ch)
            self._uni_left -= 1
            if self._uni_left == 0:
                self._str_phase = 0
        else:
            self._fail()
        return None

    def _end_string(self) -> Any | None:
        if self._depth == 0:
            return self._decode()
        if self._stack[-1][1] == "key":
            self._stack[-1][1] = "colon"
        elif self._stack[-1][1] == "value":
            self._stack[-1][1] = "comma_or_close"
        return None

    # ---- number parsing ----

    def _number_char(self, ch: str) -> Any | None:
        p = self._num_phase
        if p == 1:
            # after '-': expecting digit
            if ch == '0':
                self._buf_append(ch); self._num_phase = 3
            elif ch.isdigit():
                self._buf_append(ch); self._num_phase = 2
            else:
                self._fail()
        elif p == 2:
            # integer part (1-9…): digit / '.' / e/E / end
            if ch.isdigit():
                self._buf_append(ch)
            elif ch == '.':
                self._buf_append(ch); self._num_phase = 4
            elif ch in 'eE':
                self._buf_append(ch); self._num_phase = 6
            else:
                return self._end_number(ch)
        elif p == 3:
            # after leading '0': '.' / e/E / end (no digit!)
            if ch.isdigit():
                self._fail()
            elif ch == '.':
                self._buf_append(ch); self._num_phase = 4
            elif ch in 'eE':
                self._buf_append(ch); self._num_phase = 6
            else:
                return self._end_number(ch)
        elif p == 4:
            # after '.': expecting digit
            if ch.isdigit():
                self._buf_append(ch); self._num_phase = 5
            else:
                self._fail()
        elif p == 5:
            # fraction digits: digit / e/E / end
            if ch.isdigit():
                self._buf_append(ch)
            elif ch in 'eE':
                self._buf_append(ch); self._num_phase = 6
            else:
                return self._end_number(ch)
        elif p == 6:
            # after e/E: sign / digit
            if ch in '+-':
                self._buf_append(ch); self._num_phase = 7
            elif ch.isdigit():
                self._buf_append(ch); self._num_phase = 8
            else:
                self._fail()
        elif p == 7:
            # after exponent sign: expecting digit
            if ch.isdigit():
                self._buf_append(ch); self._num_phase = 8
            else:
                self._fail()
        elif p == 8:
            # exponent digits: digit / end
            if ch.isdigit():
                self._buf_append(ch)
            else:
                return self._end_number(ch)
        return None

    def _end_number(self, ch: str) -> Any | None:
        """Called when ch cannot continue the number.  ch is NOT part of the number."""
        self._num_phase = 0
        if self._depth == 0:
            val = self._decode()
            if ch in '{[\"':
                self._begin_value(ch)
            return val
        # nested: update parent, replay ch against container grammar
        self._stack[-1][1] = "comma_or_close"
        return self._container_char(ch)

    # ---- literal parsing ----

    def _literal_char(self, ch: str) -> Any | None:
        if ch == self._lit_target[self._lit_pos]:
            self._buf_append(ch)
            self._lit_pos += 1
            if self._lit_pos >= len(self._lit_target):
                self._lit_target = ""
                if self._depth == 0:
                    self._after_top = "literal"
                else:
                    self._stack[-1][1] = "comma_or_close"
            return None
        self._fail()

    # ---- helpers ----

    def _begin_value(self, ch: str) -> None:
        self._val_start = self._offset
        self._buf = [ch]
        self._check_limit()
        if ch == '{':
            self._stack.append([True, "key"]); self._depth = 1
        elif ch == '[':
            self._stack.append([False, "value"]); self._depth = 1
        elif ch == '"':
            self._in_str = True; self._str_phase = 0
        elif ch == '-':
            self._num_phase = 1
        elif ch in '123456789':
            self._num_phase = 2
        elif ch == '0':
            self._num_phase = 3
        elif ch == 't':
            self._lit_target = "true"; self._lit_pos = 1
        elif ch == 'f':
            self._lit_target = "false"; self._lit_pos = 1
        elif ch == 'n':
            self._lit_target = "null"; self._lit_pos = 1

    def _begin_nested(self, ch: str) -> None:
        self._buf_append(ch)
        if ch == '{':
            self._stack.append([True, "key"]); self._depth += 1
        elif ch == '[':
            self._stack.append([False, "value"]); self._depth += 1
        elif ch == '"':
            self._in_str = True; self._str_phase = 0
        elif ch == '-':
            self._num_phase = 1
        elif ch in '123456789':
            self._num_phase = 2
        elif ch == '0':
            self._num_phase = 3
        elif ch == 't':
            self._lit_target = "true"; self._lit_pos = 1
        elif ch == 'f':
            self._lit_target = "false"; self._lit_pos = 1
        elif ch == 'n':
            self._lit_target = "null"; self._lit_pos = 1

    def _buf_append(self, ch: str) -> None:
        self._buf.append(ch)
        self._check_limit()

    def _check_limit(self) -> None:
        if len(self._buf) > self._max_buffer:
            self._errored = True
            raise BufferLimitError(
                f"Value exceeds {self._max_buffer} characters",
                self._val_start + self._max_buffer,
            )

    def _decode(self) -> Any:
        text = ''.join(self._buf)
        self._buf = []
        return json.loads(text)

    def _fail(self) -> None:
        self._errored = True
        raise JSONStreamError(
            f"Invalid JSON at offset {self._offset}",
            self._offset,
        )
```

### test_solution.py
```python
"""Tests for solution.py – incremental JSON stream decoder."""
import json
import math
import pytest
import solution
from solution import (
    JSONStreamDecoder,
    JSONStreamError,
    IncompleteJSONError,
    BufferLimitError,
)


# ---------------------------------------------------------------------------
# helpers
# ---------------------------------------------------------------------------

def feed_one(text: str, **kw):
    d = JSONStreamDecoder(**kw)
    r = d.feed(text)
    return d, r


def full(text: str, **kw):
    d = JSONStreamDecoder(**kw)
    r = d.feed(text)
    r += d.close()
    return r


# ---------------------------------------------------------------------------
# basic values
# ---------------------------------------------------------------------------

class TestBasicValues:
    def test_empty_string_top(self):
        assert full('""') == [""]

    def test_simple_string(self):
        assert full('"hello"') == ["hello"]

    def test_string_with_escapes(self):
        assert full(r'"a\tb\\c\"d"') == ['a\tb\\c"d']

    def test_unicode_escape(self):
        assert full(r'"\u00e9"') == ["é"]

    def test_surrogate_pair(self):
        assert full(r'"\ud83d\ude00"') == ["\U0001f600"]

    def test_lone_surrogate_accepted(self):
        assert full(r'"\ud800"') == ["\ud800"]

    def test_integer(self):
        assert full("42") == [42]

    def test_negative_integer(self):
        assert full("-7") == [-7]

    def test_zero(self):
        assert full("0") == [0]

    def test_float(self):
        assert full("3.14") == [3.14]

    def test_neg_zero_float(self):
        r = full("-0.0")
        assert r == [-0.0]
        assert math.copysign(1, r[0]) == -1

    def test_exponent(self):
        assert full("1e10") == [1e10]

    def test_large_exp_inf(self):
        assert full("1E400") == [float('inf')]

    def test_big_integer(self):
        n = 10**50
        assert full(str(n)) == [n]

    def test_true(self):
        assert full("true") == [True]

    def test_false(self):
        assert full("false") == [False]

    def test_null(self):
        assert full("null") == [None]

    def test_empty_object(self):
        assert full("{}") == [{}]

    def test_empty_array(self):
        assert full("[]") == [[]]

    def test_object(self):
        assert full('{"a":1,"b":[2,3]}') == [{"a": 1, "b": [2, 3]}]

    def test_nested(self):
        assert full('{"a":{"b":[1,{"c":null}]}}') == [{"a": {"b": [1, {"c": None}]}}]

    def test_duplicate_key_last_wins(self):
        assert full('{"a":1,"a":2}') == [{"a": 2}]

    def test_deep_nesting_1000(self):
        text = "[" * 1000 + "]" * 1000
        r = full(text)
        assert len(r) == 1
        v = r[0]
        for _ in range(999):
            v = v[0]
        assert v == []

    def test_number_at_end_returned_by_close(self):
        d = JSONStreamDecoder()
        assert d.feed("12") == []
        assert d.close() == [12]

    def test_literal_at_end_returned_by_close(self):
        d = JSONStreamDecoder()
        assert d.feed("true") == []
        assert d.close() == [True]


# ---------------------------------------------------------------------------
# multiple top-level values
# ---------------------------------------------------------------------------

class TestMultipleValues:
    def test_two_numbers(self):
        assert full("1 2") == [1, 2]

    def test_adjacent_no_ws(self):
        assert full('{}[]"x"1') == [{}, [], "x", 1]

    def test_number_followed_by_array(self):
        assert full("1[2]") == [1, [2]]

    def test_true_followed_by_string(self):
        assert full('true"x"') == [True, "x"]

    def test_many_values_one_chunk(self):
        vals = [json.dumps({"i": i}) for i in range(50000)]
        text = "".join(vals)
        assert full(text) == [json.loads(v) for v in vals]


# ---------------------------------------------------------------------------
# chunked delivery
# ---------------------------------------------------------------------------

class TestChunkedDelivery:
    def test_string_split_mid_escape(self):
        d = JSONStreamDecoder()
        assert d.feed(r'"ab\u00') == []
        assert d.feed("e9\"") == ["é"]

    def test_string_split_mid_surrogate(self):
        d = JSONStreamDecoder()
        assert d.feed(r'"\ud83') == []
        assert d.feed('d\ude00"') == ["\U0001f600"]

    def test_number_split_mid_number(self):
        d = JSONStreamDecoder()
        assert d.feed("12") == []
        assert d.feed("34 ") == [1234]

    def test_container_split(self):
        d = JSONStreamDecoder()
        assert d.feed('{"a":') == []
        assert d.feed("1}") == [{"a": 1}]

    def test_literal_split(self):
        d = JSONStreamDecoder()
        assert d.feed("tru") == []
        assert d.feed("e ") == [True]

    def test_number_mid_fraction(self):
        d = JSONStreamDecoder()
        assert d.feed("1.") == []
        assert d.feed("5 ") == [1.5]

    def test_number_mid_exponent(self):
        d = JSONStreamDecoder()
        assert d.feed("1e") == []
        assert d.feed("+2 ") == [100.0]

    def test_one_char_at_a_time(self):
        text = '{"x":[1,2,3],"y":"hello"}'
        d = JSONStreamDecoder()
        collected = []
        for ch in text:
            collected += d.feed(ch)
        collected += d.close()
        assert collected == [json.loads(text)]

    def test_64_char_chunks_large_string(self):
        # 8 MB string value fed in 64-char chunks
        inner = "a" * (8_000_000 - 2)
        text = f'"{inner}"'
        d = JSONStreamDecoder(max_buffer=10_000_000)
        results = []
        for i in range(0, len(text), 64):
            results += d.feed(text[i:i+64])
        results += d.close()
        assert results == [inner]
        assert len(results[0]) == 8_000_000 - 2


# ---------------------------------------------------------------------------
# whitespace handling
# ---------------------------------------------------------------------------

class TestWhitespace:
    def test_leading_whitespace(self):
        assert full("   \t\n\r{}") == [{}]

    def test_whitespace_inside_container(self):
        assert full("{ \"a\" : 1 }") == [{"a": 1}]

    def test_whitespace_between_values(self):
        assert full("1  \n 2  \r 3") == [1, 2, 3]

    def test_trailing_whitespace_close(self):
        d = JSONStreamDecoder()
        assert d.feed("12") == []
        assert d.feed("   ") == [12]
        assert d.close() == []

    def test_non_ascii_space_is_not_whitespace(self):
        d = JSONStreamDecoder()
        # U+00A0 (non-breaking space) is NOT JSON whitespace
        with pytest.raises(JSONStreamError) as exc_info:
            d.feed("1\u00a0")
        assert exc_info.value.offset == 1


# ---------------------------------------------------------------------------
# number terminator rules
# ---------------------------------------------------------------------------

class TestNumberTerminator:
    def test_1_2_is_two(self):
        assert full("1 2") == [1, 2]

    def test_12_is_one(self):
        assert full("12") == [12]

    def test_1_minus_2_error(self):
        d = JSONStreamDecoder()
        with pytest.raises(JSONStreamError) as exc_info:
            d.feed("1-2")
        assert exc_info.value.offset == 1

    def test_01_error(self):
        d = JSONStreamDecoder()
        with pytest.raises(JSONStreamError) as exc_info:
            d.feed("01")
        assert exc_info.value.offset == 1

    def test_comma_after_top_number_error(self):
        d = JSONStreamDecoder()
        with pytest.raises(JSONStreamError) as exc_info:
            d.feed("1,2")
        assert exc_info.value.offset == 1

    def test_number_terminated_by_brace(self):
        assert full("1{}") == [1, {}]

    def test_number_terminated_by_bracket(self):
        assert full("1[]") == [1, []]

    def test_number_terminated_by_string(self):
        assert full('1"x"') == [1, "x"]


# ---------------------------------------------------------------------------
# literal terminator rules
# ---------------------------------------------------------------------------

class TestLiteralTerminator:
    def test_true1_error(self):
        d = JSONStreamDecoder()
        with pytest.raises(JSONStreamError) as exc_info:
            d.feed("true1")
        assert exc_info.value.offset == 4

    def test_nullnull_error(self):
        d = JSONStreamDecoder()
        with pytest.raises(JSONStreamError) as exc_info:
            d.feed("nullnull")
        assert exc_info.value.offset == 4

    def test_true_followed_by_open_brace(self):
        assert full("true{}") == [True, {}]

    def test_true_followed_by_string(self):
        assert full('true"s"') == [True, "s"]


# ---------------------------------------------------------------------------
# self-delimiting adjacency
# ---------------------------------------------------------------------------

class TestSelfDelimiting:
    def test_adjacent_containers(self):
        assert full("[][") == [[], []]  # first [] done, second [ in progress
        d = JSONStreamDecoder()
        r = d.feed("[][")
        assert r == [[]]
        assert d.pending() == 1
        r2 = d.close()  # incomplete!
        assert r2  # should raise
        # Actually close() raises IncompleteJSONError
        # Let me re-test
        d2 = JSONStreamDecoder()
        r = d2.feed("[]{}\"x\"")
        assert r == [[], {}, "x"]


# ---------------------------------------------------------------------------
# error offsets
# ---------------------------------------------------------------------------

class TestErrorOffsets:
    def test_comma_in_array(self):
        d = JSONStreamDecoder()
        with pytest.raises(JSONStreamError) as exc_info:
            d.feed("[1,]")
        assert exc_info.value.offset == 3

    def test_dot_then_close(self):
        d = JSONStreamDecoder()
        with pytest.raises(JSONStreamError) as exc_info:
            d.feed("[1.]")
        assert exc_info.value.offset == 3

    def test_tru_brace(self):
        d = JSONStreamDecoder()
        with pytest.raises(JSONStreamError) as exc_info:
            d.feed('{"a":tru}')
        assert exc_info.value.offset == 8

    def test_string_bad_escape(self):
        d = JSONStreamDecoder()
        with pytest.raises(JSONStreamError) as exc_info:
            d.feed('"abc\\x"')
        assert exc_info.value.offset == 5

    def test_leading_zero_in_array(self):
        d = JSONStreamDecoder()
        with pytest.raises(JSONStreamError) as exc_info:
            d.feed("[01]")
        assert exc_info.value.offset == 2

    def test_raw_newline_in_string(self):
        d = JSONStreamDecoder()
        with pytest.raises(JSONStreamError) as exc_info:
            d.feed('"a\nb"')
        assert exc_info.value.offset == 2

    def test_letter_after_array(self):
        d = JSONStreamDecoder()
        with pytest.raises(JSONStreamError) as exc_info:
            d.feed("[1]x")
        assert exc_info.value.offset == 3

    def test_number_where_colon_expected(self):
        d = JSONStreamDecoder()
        with pytest.raises(JSONStreamError) as exc_info:
            d.feed('{"a" 1}')
        assert exc_info.value.offset == 5

    def test_closing_brace_at_top_level(self):
        d = JSONStreamDecoder()
        with pytest.raises(JSONStreamError) as exc_info:
            d.feed("}")
        assert exc_info.value.offset == 0

    def test_comma_at_top_level(self):
        d = JSONStreamDecoder()
        with pytest.raises(JSONStreamError) as exc_info:
            d.feed(",")
        assert exc_info.value.offset == 0


# ---------------------------------------------------------------------------
# post-error behaviour
# ---------------------------------------------------------------------------

class TestPostError:
    def test_feed_after_error(self):
        d = JSONStreamDecoder()
        with pytest.raises(JSONStreamError):
            d.feed("[")
        with pytest.raises(JSONStreamError):
            d.feed("1]")
        with pytest.raises(JSONStreamError):
            d.close()

    def test_close_after_error(self):
        d = JSONStreamDecoder()
        with pytest.raises(JSONStreamError):
            d.feed("}")
        with pytest.raises(JSONStreamError):
            d.close()

    def test_values_before_error_lost(self):
        d = JSONStreamDecoder()
        # feed("1 2") would return [1,2] normally, but if error occurs mid-chunk,
        # values completed in that same chunk are lost.
        with pytest.raises(JSONStreamError):
            d.feed("1 2,")
        # The 1 and 2 are lost per spec.
        with pytest.raises(JSONStreamError):
            d.feed("x")


# ---------------------------------------------------------------------------
# close behaviour
# ---------------------------------------------------------------------------

class TestClose:
    def test_close_empty(self):
        d = JSONStreamDecoder()
        assert d.close() == []

    def test_close_after_complete(self):
        d = JSONStreamDecoder()
        d.feed("{}")
        assert d.close() == []

    def test_close_number_pending(self):
        d = JSONStreamDecoder()
        d.feed("42")
        assert d.close() == [42]

    def test_close_literal_pending(self):
        d = JSONStreamDecoder()
        d.feed("false")
        assert d.close() == [False]

    def test_close_incomplete_container(self):
        d = JSONStreamDecoder()
        d.feed("[1,2")
        with pytest.raises(IncompleteJSONError) as exc_info:
            d.close()
        assert exc_info.value.offset == 4

    def test_close_incomplete_string(self):
        d = JSONStreamDecoder()
        d.feed('"abc')
        with pytest.raises(IncompleteJSONError) as exc_info:
            d.close()
        assert exc_info.value.offset == 4

    def test_close_partial_number(self):
        d = JSONStreamDecoder()
        d.feed("1.")
        with pytest.raises(IncompleteJSONError) as exc_info:
            d.close()
        assert exc_info.value.offset == 2

    def test_close_partial_literal(self):
        d = JSONStreamDecoder()
        d.feed("tru")
        with pytest.raises(IncompleteJSONError) as exc_info:
            d.close()
        assert exc_info.value.offset == 3

    def test_close_after_close(self):
        d = JSONStreamDecoder()
        d.close()
        with pytest.raises(JSONStreamError):
            d.close()

    def test_feed_after_close(self):
        d = JSONStreamDecoder()
        d.close()
        with pytest.raises(JSONStreamError):
            d.feed("1")

    def test_close_trailing_whitespace(self):
        d = JSONStreamDecoder()
        d.feed("12   ")
        # 12 was terminated by space, already returned
        assert d.close() == []


