class TestPending:
    def test_pending_between_values(self):
        d = JSONStreamDecoder()
        assert d.pending() == 0

    def test_pending_number_awaiting_terminator(self):
        d = JSONStreamDecoder()
        d.feed("  12")
        assert d.pending() == 2

    def test_pending_incomplete_container(self):
        d = JSONStreamDecoder()
        d.feed("[1,2")
        assert d.pending() == 4

    def test_pending_incomplete_string(self):
        d = JSONStreamDecoder()
        d.feed('"ab')
        assert d.pending() == 3

    def test_pending_zero_after_complete(self):
        d = JSONStreamDecoder()
        d.feed("12 ")
        assert d.pending() == 0

    def test_pending_zero_after_close(self):
        d = JSONStreamDecoder()
        d.feed("12")
        d.close()
        assert d.pending() == 0


