class TestBufferLimit:
    def test_exact_limit_ok(self):
        d = JSONStreamDecoder(max_buffer=5)
        assert d.feed('"abcd"') == ["abcd"]

    def test_exceed_limit(self):
        d = JSONStreamDecoder(max_buffer=3)
        with pytest.raises(BufferLimitError) as exc_info:
            d.feed('"abcd"')
        assert exc_info.value.offset == 3  # val_start(0) + 3

    def test_limit_mid_value(self):
        d = JSONStreamDecoder(max_buffer=5)
        with pytest.raises(BufferLimitError) as exc_info:
            d.feed('{"ab":"cdefgh"}')
        # value starts at 0, 6th char is at offset 5
        assert exc_info.value.offset == 5

    def test_limit_number_terminator_not_counted(self):
        d = JSONStreamDecoder(max_buffer=2)
        # "12 " → number is 2 chars, space is terminator (not counted)
        assert d.feed("12 ") == [12]

    def test_limit_whitespace_inside_counts(self):
        d = JSONStreamDecoder(max_buffer=5)
        # "{  }" is 4 chars → ok
        assert d.feed("{  }") == [{}]
        # "{  x}" is 5 chars → ok
        d2 = JSONStreamDecoder(max_buffer=5)
        with pytest.raises(JSONStreamError):
            d2.feed("{  x}")  # x after key is invalid JSON → not buffer issue

    def test_limit_across_chunks(self):
        d = JSONStreamDecoder(max_buffer=4)
        assert d.feed('{"a"') == []
        with pytest.raises(BufferLimitError):
            d.feed(':1}')

    def test_terminator_not_counted_number(self):
        d = JSONStreamDecoder(max_buffer=3)
        # "123" is 3 chars (ok), terminator ' ' not counted
        assert d.feed("123 ") == [123]

